$ProgressPreference='SilentlyContinue'
foreach ($u in @("https://aws-ap-south-1.entire.io/.well-known/entire.json","https://aws-ap-south-1.entire.io/.well-known/openid-configuration","https://aws-ap-south-1.entire.io/")) {
  try { $r = Invoke-WebRequest -Uri $u -MaximumRedirection 0 -ErrorAction Stop; "OK  $u -> $($r.StatusCode)"; ($r.Content | Select-Object -First 1).Substring(0,[Math]::Min(400,$r.Content.Length)) }
  catch { "ERR $u -> $($_.Exception.Response.StatusCode.value__) $($_.Exception.Message.Split([char]10)[0])" }
}

$env:Path += ";C:\Users\empad\bin\entire"; $ProgressPreference='SilentlyContinue'
$tok = (entire auth token 2>&1 | Out-String).Trim()
if (-not $tok -or $tok -match '\s') { "TOKEN ALINAMADI (uzunluk=$($tok.Length))"; exit 1 }
"Token alindi (uzunluk=$($tok.Length))"
$u = "https://aws-ap-south-1.entire.io/gh/keparlak/NumWordify/info/refs?service=git-upload-pack"
try { $r = Invoke-WebRequest -Uri $u -Headers @{Authorization="Bearer $tok"} -ErrorAction Stop; "HTTP $($r.StatusCode) - OK, $($r.RawContentLength) bytes" }
catch { $resp=$_.Exception.Response; "HTTP $($resp.StatusCode.value__) $($resp.StatusCode)"; try { (New-Object IO.StreamReader($resp.GetResponseStream())).ReadToEnd().Substring(0,300) } catch {} }

$env:Path += ";C:\Users\empad\bin\entire"; "=== api --help ==="; entire api --help 2>&1 | Select-Object -First 25
"`n=== auth server DNS probe ==="
$ProgressPreference='SilentlyContinue'
foreach ($h in @("in.auth.entire.io","ap.auth.entire.io","apac.auth.entire.io","ap-south.auth.entire.io","india.auth.entire.io","eu.auth.entire.io","aws-ap-south-1.auth.entire.io")) {
  $dns = $null; try { $dns = [System.Net.Dns]::GetHostEntry($h) } catch {}
  if ($dns) { "RESOLVES  $h" } else { "no-dns    $h" }
}

